        "<p>말로 해도 되지만 나중에 다투지 않으려면 문자나 내용증명으로 남기세요. 문구는 <a href=\"form-notice.html\">통지문 예시</a>에 있습니다.</p>",
        "<h2>거절할 수 있는 9가지</h2>",
