            ["거짓·부정한 방법", "신분을 속이는 등 부정하게 임차한 경우"],
            ["합의 보상", "집주인이 상당한 보상을 하기로 합의한 경우"],
            ["멸실", "집이 무너지거나 없어져 살 수 없는 경우"],
            ["철거·재건축", "계약 당시 고지했거나, 안전상 문제로 철거·재건축하는 경우"],
            ["그 밖의 중대한 사유", "임차인으로서 의무를 크게 위반한 경우"],
