        "<p>그래서 3년은 은행이 정한 관행이 아니라 <strong>법정 상한</strong>입니다. 상품에 따라 2년이나 1년으로 더 짧게 잡기도 하지만, 3년을 넘기는 경우는 없습니다. 내 대출의 면제일은 <strong>실행일 + 부과 기간</strong>입니다.</p>",
