        "<h2>정리</h2>",
        "<ul><li>면제일은 <strong>대출 실행일 + 부과 기간</strong>. 계산기에 실행일을 넣으면 날짜가 나옵니다</li><li>수수료는 남은 일수에 비례해 줄어듭니다. 급하지 않으면 기다릴수록 유리합니다</li><li>갈아타기는 <strong>수수료 ÷ 월 절약액</strong>으로 손익분기 개월 수를 구해 판단합니다</li><li>정확한 금액은 은행에 확인하세요. 약정서의 수수료율과 부과 기간이 상품마다 다릅니다</li></ul>",
