            ["기납부세액", "1년 동안 회사가 월급에서 이미 뗀 소득세 (전 직장분 포함)"],
            ["차감징수세액", "결정세액 − 기납부세액. 마이너스(−)면 돌려받고, 플러스면 더 냄"],
